import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int b = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int[] oddCount = new int[n + 1];
        int[] evenCount = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            if (a[i - 1] % 2 == 1) {
                oddCount[i] = oddCount[i - 1] + 1;
                evenCount[i] = evenCount[i - 1];
            } else {
                oddCount[i] = oddCount[i - 1];
                evenCount[i] = evenCount[i - 1] + 1;
            }
        }

        int lastIndex = 0;
        PriorityQueue<Integer> diffs = new PriorityQueue<>();
        for (int i = 1; i < n; i++) {
            int oDiff = oddCount[i] - oddCount[lastIndex];
            int eDiff = evenCount[i] - evenCount[lastIndex];
            if (oDiff == eDiff) {
                diffs.add(Math.abs(a[i] - a[i - 1]));
                lastIndex = i;
            }
        }

        int total = 0;
        int count = 0;
        while (!diffs.isEmpty() && total + diffs.peek() <= b) {
            total += diffs.poll();
            count++;
        }
        System.out.println(count);
    }
}
