#include <iostream>
#include <vector>
#include <queue>
#include <cmath>

int main() {
    int n, b;
    std::cin >> n >> b;
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    std::vector<int> oddCount(n + 1, 0);
    std::vector<int> evenCount(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        if (a[i - 1] % 2 == 1) {
            oddCount[i] = oddCount[i - 1] + 1;
            evenCount[i] = evenCount[i - 1];
        } else {
            oddCount[i] = oddCount[i - 1];
            evenCount[i] = evenCount[i - 1] + 1;
        }
    }

    int lastIndex = 0;
    std::priority_queue<int, std::vector<int>, std::greater<int>> diffs;
    for (int i = 1; i < n; ++i) {
        int oDiff = oddCount[i] - oddCount[lastIndex];
        int eDiff = evenCount[i] - evenCount[lastIndex];
        if (oDiff == eDiff) {
            diffs.push(std::abs(a[i] - a[i - 1]));
            lastIndex = i;
        }
    }

    int total = 0;
    int count = 0;
    while (!diffs.empty() && total + diffs.top() <= b) {
        total += diffs.top();
        diffs.pop();
        ++count;
    }
    std::cout << count << std::endl;
    return 0;
}

